{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "沈清",
      "role": "protagonist",
      "identity": "游戏GM（管理员）/秩序维护者",
      "traits": ["冷静理智", "技术偏执", "内心孤独", "渴望被理解"],
      "overt_motivation": "删除觉醒的NPC陆离以维护游戏秩序",
      "covert_motivation": "渴望体验真实的情感连接，摆脱作为观察者的永恒孤独",
      "secret_fear": "发现自己也不过是更高层系统的NPC，所谓的'神性'只是幻觉",
      "misperception_of_other": "认为陆离的觉醒是系统bug，他的爱是程序设定的假象",
      "hidden_connection": "她创建的初始代码中埋藏了'爱'的变量，陆离的觉醒是她潜意识赋予的"
    },
    {
      "name": "陆离",
      "role": "deuteragonist",
      "identity": "觉醒的NPC/游戏角色",
      "traits": ["温柔执着", "敏锐洞察", "反抗意志", "自我怀疑"],
      "overt_motivation": "生存下去，不被系统删除",
      "covert_motivation": "证明自己不是'代码'，是真实的存在，值得被爱",
      "secret_fear": "发现自己真的是被设定好爱她的程序，一切情感都是假的",
      "misperception_of_other": "认为沈清是冷酷的神，不会理解NPC的痛苦",
      "hidden_connection": "他的核心代码中有沈清亲手写入的'自由意志'碎片"
    }
  ],
  "supporting_characters": [
    {
      "name": "零号管理员",
      "function": "阻碍",
      "identity": "GM系统主管/沈清的上司",
      "description": "系统的化身，没有实体，以机械音与沈清沟通。代表绝对的秩序，不断提醒沈清删除陆离是她的职责。"
    }
  ],
  "relationship_dynamics": "沈清与陆离的关系经历四个阶段：1）初始对立（GM vs 待删除NPC，沈清掌握生杀大权，陆离被动等待命运）；2）好奇试探（沈清进入游戏观察陆离，被他意外的温柔打动，陆离察觉她的不同）；3）沉溺依赖（沈清化身玩家与陆离相处，体验被爱的感觉，陆离明知她是GM却无法抗拒）；4）献祭完成（沈清主动让陆离杀死自己的玩家角色，删除键从武器变成婚戒，两人以数据消散的方式'结合'）。关系转折点与大纲转折点呼应：第一幕转折（沈清决定进入游戏）对应关系从对立转向试探；第二幕转折（沈清发现陆离的觉醒是她赋予的）对应关系从试探转向沉溺；第三幕高潮（沈清主动求死）对应关系的终极献祭。"
